/* test_bus_wire.c: slice 1 of the event-bus feature tree.
 *
 * Three jobs, deliberately kept separate:
 *
 *   1. Hold the codec to the committed golden vectors in
 *      src/tests/fixtures/bus/wire_vectors.tsv. Those bytes are generated by
 *      scripts/gen_bus_wire_vectors.py, which re-declares the byte layout from
 *      the spec independently of this codec — so agreement is evidence about
 *      the wire, not the codec agreeing with itself. The table is the source of
 *      truth here: this test parses its field column into a frame and checks
 *      the codec against it in both directions. It never constructs the
 *      expected bytes.
 *
 *   2. Exercise the message-pattern contract from an independently enumerated
 *      matrix, so a pattern or placement added to bus_wire.h later cannot
 *      silently go untested.
 *
 *   3. Reject every malformed frame the decoder is responsible for catching.
 *
 * Regenerating the vectors is a separate, reviewable act: run the Python
 * generator and commit the byte diff. This test has no --regen path, because a
 * test that can rewrite its own expectations is not a test.
 */
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <aimee/core/event_bus/bus_wire.h>

/* Set by the build so the test is cwd-independent. */
#ifndef BUS_VECTOR_DIR
#define BUS_VECTOR_DIR "fixtures/bus"
#endif
#define VECTOR_PATH BUS_VECTOR_DIR "/wire_vectors.tsv"

/* ------------------------------------------------------------------ */
/* helpers                                                             */

static int hex_decode(const char *in, uint8_t *out, size_t outsz, size_t *n)
{
   size_t len = strlen(in);
   if (len % 2 != 0 || len / 2 > outsz)
      return 0;
   for (size_t i = 0; i < len; i += 2)
   {
      int hi = -1, lo = -1;
      for (int k = 0; k < 16; k++)
      {
         if ("0123456789abcdef"[k] == in[i])
            hi = k;
         if ("0123456789abcdef"[k] == in[i + 1])
            lo = k;
      }
      if (hi < 0 || lo < 0)
         return 0;
      out[i / 2] = (uint8_t)((hi << 4) | lo);
   }
   *n = len / 2;
   return 1;
}

static void hex_encode(const uint8_t *in, size_t n, char *out)
{
   static const char *h = "0123456789abcdef";
   for (size_t i = 0; i < n; i++)
   {
      out[2 * i] = h[in[i] >> 4];
      out[2 * i + 1] = h[in[i] & 0x0f];
   }
   out[2 * n] = '\0';
}

/* A behavioural check that survives -DNDEBUG. assert() would compile these
 * away, leaving a test that passes because it stopped looking. */
static void must(int cond, const char *what)
{
   if (!cond)
   {
      fprintf(stderr, "FAIL: %s\n", what);
      abort();
   }
}

/* Parse one "k=v;k=v" field column into a frame.
 *
 * The table is authoritative, so this parser is strict in all three directions
 * a corrupted table could otherwise slip through: an unknown key is an error
 * rather than a default, a repeated key is an error rather than an overwrite,
 * and a value that does not consume its whole token is an error rather than a
 * silent zero. A lenient parser here would let a damaged vector assert
 * something that was never actually checked. */
typedef enum
{
   FLD_FLAGS,
   FLD_VER,
   FLD_KIND,
   FLD_PRINCIPAL,
   FLD_CORR,
   FLD_SEQ,
   FLD_LTS,
   FLD_PREF,
   FLD_PLEN,
   FLD_SRC,
   FLD_DST,
   FLD_GEN,
   FLD_COUNT
} field_id_t;

static const char *const FIELD_NAMES[FLD_COUNT] = {
    "flags", "ver", "kind", "principal", "corr", "seq", "lts", "pref", "plen", "src", "dst", "gen"};

static unsigned long long parse_u(const char *name, const char *key, const char *text,
                                  unsigned long long limit)
{
   if (*text == '\0' || *text == '-')
   {
      fprintf(stderr, "vector '%s': field '%s' has no value\n", name, key);
      exit(1);
   }
   char *end = NULL;
   errno = 0;
   unsigned long long v = strtoull(text, &end, 0);
   if (errno != 0 || !end || *end != '\0')
   {
      fprintf(stderr, "vector '%s': field '%s' value '%s' is not a whole number\n", name, key,
              text);
      exit(1);
   }
   if (v > limit)
   {
      fprintf(stderr, "vector '%s': field '%s' value %llu exceeds its width\n", name, key, v);
      exit(1);
   }
   return v;
}

static void parse_fields(const char *name, const char *spec, bus_frame_t *f)
{
   char buf[512];
   if (snprintf(buf, sizeof buf, "%s", spec) >= (int)sizeof buf)
   {
      fprintf(stderr, "vector '%s': field column too long\n", name);
      exit(1);
   }
   memset(f, 0, sizeof *f);

   int seen[FLD_COUNT];
   memset(seen, 0, sizeof seen);

   for (char *tok = strtok(buf, ";"); tok; tok = strtok(NULL, ";"))
   {
      char *eq = strchr(tok, '=');
      if (!eq)
      {
         fprintf(stderr, "vector '%s': malformed field '%s'\n", name, tok);
         exit(1);
      }
      *eq = '\0';
      const char *k = tok;
      const char *text = eq + 1;

      int id = -1;
      for (int i = 0; i < FLD_COUNT; i++)
         if (!strcmp(k, FIELD_NAMES[i]))
            id = i;
      if (id < 0)
      {
         fprintf(stderr, "vector '%s': unknown field '%s'\n", name, k);
         exit(1);
      }
      if (seen[id])
      {
         fprintf(stderr, "vector '%s': field '%s' appears twice\n", name, k);
         exit(1);
      }
      seen[id] = 1;

      switch ((field_id_t)id)
      {
      case FLD_FLAGS:
         f->hdr_flags = (uint16_t)parse_u(name, k, text, UINT16_MAX);
         break;
      case FLD_VER:
         f->wire_version = (uint16_t)parse_u(name, k, text, UINT16_MAX);
         break;
      case FLD_KIND:
         f->event_kind = (uint32_t)parse_u(name, k, text, UINT32_MAX);
         break;
      case FLD_PRINCIPAL:
         f->principal_ref = (uint32_t)parse_u(name, k, text, UINT32_MAX);
         break;
      case FLD_CORR:
         f->correlation_id = parse_u(name, k, text, UINT64_MAX);
         break;
      case FLD_SEQ:
         f->seq = parse_u(name, k, text, UINT64_MAX);
         break;
      case FLD_LTS:
         f->logical_ts = parse_u(name, k, text, UINT64_MAX);
         break;
      case FLD_PREF:
         f->payload_ref = parse_u(name, k, text, UINT64_MAX);
         break;
      case FLD_PLEN:
         f->payload_len = (uint32_t)parse_u(name, k, text, UINT32_MAX);
         break;
      case FLD_SRC:
         f->src_handle = (uint32_t)parse_u(name, k, text, UINT32_MAX);
         break;
      case FLD_DST:
         f->dst_handle = (uint32_t)parse_u(name, k, text, UINT32_MAX);
         break;
      case FLD_GEN:
         f->generation = (uint32_t)parse_u(name, k, text, UINT32_MAX);
         break;
      case FLD_COUNT:
         break;
      }
   }

   for (int i = 0; i < FLD_COUNT; i++)
      if (!seen[i])
      {
         fprintf(stderr, "vector '%s': missing field '%s'\n", name, FIELD_NAMES[i]);
         exit(1);
      }
}

/* ------------------------------------------------------------------ */
/* 1. the committed vectors                                            */

/* Flag combinations that must appear somewhere in the table. Declared here
 * independently of the table so a pattern added to bus_wire.h without a vector
 * is caught, rather than the table quietly defining its own coverage. */
typedef struct
{
   const char *what;
   uint16_t flags;
} required_shape_t;

static const required_shape_t REQUIRED_SHAPES[] = {
    {"notification, no payload", BUS_F_NOTIFICATION},
    {"notification, inline", BUS_F_NOTIFICATION | BUS_F_INLINE},
    {"notification, arena", BUS_F_NOTIFICATION | BUS_F_ARENA},
    {"request", BUS_F_REQUEST | BUS_F_ARENA},
    {"reply", BUS_F_REPLY | BUS_F_INLINE},
    {"reply, no payload", BUS_F_REPLY},
    {"cancel", BUS_F_CANCEL},
    {"control class", BUS_F_NOTIFICATION | BUS_F_CONTROL | BUS_F_INLINE},
};
#define REQUIRED_SHAPE_COUNT (sizeof REQUIRED_SHAPES / sizeof REQUIRED_SHAPES[0])

static size_t verify_vectors(void)
{
   FILE *fp = fopen(VECTOR_PATH, "r");
   if (!fp)
   {
      fprintf(stderr, "cannot open %s\n", VECTOR_PATH);
      exit(1);
   }

   int shape_seen[REQUIRED_SHAPE_COUNT];
   memset(shape_seen, 0, sizeof shape_seen);

   size_t n = 0, negatives = 0, geometry_checked = 0;
   char line[2048];
   while (fgets(line, sizeof line, fp))
   {
      if (line[0] == '#' || line[0] == '\n')
         continue;
      char *nl = strchr(line, '\n');
      if (nl)
         *nl = '\0';

      char *name = strtok(line, "\t");
      char *expect = strtok(NULL, "\t");
      char *hex = strtok(NULL, "\t");
      char *fields = strtok(NULL, "\t");
      if (!name || !expect || !hex || !fields)
      {
         fprintf(stderr, "malformed vector line %zu\n", n + 1);
         exit(1);
      }

      /* A negative row has no valid frame to describe, so it carries "-" in the
       * field column: the bytes and the expected refusal are the whole claim. */
      int negative = (strcmp(fields, "-") == 0);
      bus_frame_t want;
      if (!negative)
         parse_fields(name, fields, &want);
      else
         memset(&want, 0, sizeof want);

      uint8_t raw[BUS_WIRE_HDR_LEN];
      size_t rawn = 0;
      if (!hex_decode(hex, raw, sizeof raw, &rawn) || rawn != BUS_WIRE_HDR_LEN)
      {
         fprintf(stderr, "vector '%s': hex is not %d bytes\n", name, BUS_WIRE_HDR_LEN);
         exit(1);
      }

      /* Decode direction: the committed bytes must yield the committed fields.
       * Both sides come from the generator, so this checks the decoder against
       * an independent statement of the layout. */
      bus_frame_t got;
      bus_wire_result_t r = bus_wire_decode(raw, rawn, &got);
      if (strcmp(bus_wire_result_name(r), expect) != 0)
      {
         fprintf(stderr, "vector '%s': decode gave %s, table says %s\n", name,
                 bus_wire_result_name(r), expect);
         exit(1);
      }
      if (negative && r == BUS_WIRE_OK)
      {
         fprintf(stderr, "vector '%s': a negative row decoded successfully\n", name);
         exit(1);
      }
      if (!negative && r == BUS_WIRE_OK && memcmp(&want, &got, sizeof want) != 0)
      {
         fprintf(stderr, "vector '%s': decoded fields differ from the table\n", name);
         exit(1);
      }

      /* Encode direction: the committed fields must yield the committed bytes.
       * Compared against the table's hex, never against freshly encoded bytes. */
      if (!negative && r == BUS_WIRE_OK)
      {
         uint8_t enc[BUS_WIRE_HDR_LEN];
         char enc_hex[2 * BUS_WIRE_HDR_LEN + 1];
         if (bus_wire_encode(&want, enc, sizeof enc) != BUS_WIRE_HDR_LEN)
         {
            fprintf(stderr, "vector '%s': encode refused a committed frame\n", name);
            exit(1);
         }
         hex_encode(enc, sizeof enc, enc_hex);
         if (strcmp(enc_hex, hex) != 0)
         {
            fprintf(stderr, "vector '%s' drifted:\n  committed %s\n  encoded   %s\n", name, hex,
                    enc_hex);
            exit(1);
         }

         for (size_t i = 0; i < REQUIRED_SHAPE_COUNT; i++)
            if (want.hdr_flags == REQUIRED_SHAPES[i].flags)
               shape_seen[i] = 1;
      }
      /* Every payload-bearing positive row also goes through the checked path,
       * twice: once with geometry that comfortably contains it, and once with
       * geometry deliberately one byte too small. Testing the checked path only
       * on a hand-built case would leave the committed vectors — the rows a
       * future client is held to — saying nothing about geometry at all. */
      if (!negative && r == BUS_WIRE_OK && got.payload_len > 0)
      {
         /* The bounded quantity depends on placement: an INLINE payload lives in
          * the ring slot at [payload_ref, payload_ref+len), so the slot must
          * contain it; an ARENA frame's payload_ref is a lease id (v2), so the
          * only wire-level bound is that payload_len not exceed the whole arena
          * (the offset/span is the lease table's business). Exercise each against
          * ample geometry and against geometry deliberately one byte too small. */
         uint32_t roomy_slot;
         uint64_t roomy_arena, tight_bound;
         if (got.hdr_flags & BUS_F_INLINE)
         {
            uint64_t end = got.payload_ref + got.payload_len;
            roomy_slot = (uint32_t)(end + 64);
            roomy_arena = end + 64;
            tight_bound = end - 1; /* slot one byte too small */
         }
         else /* ARENA: bound is arena_size vs payload_len */
         {
            roomy_slot = (uint32_t)(BUS_WIRE_HDR_LEN + got.payload_len + 64);
            roomy_arena = (uint64_t)got.payload_len + 64;
            tight_bound = (uint64_t)got.payload_len - 1; /* arena one byte too small */
         }

         bus_frame_t chk;
         if (bus_wire_decode_checked(raw, rawn, roomy_slot, roomy_arena, &chk) != BUS_WIRE_OK)
         {
            fprintf(stderr, "vector '%s': checked decode refused it under ample geometry\n", name);
            exit(1);
         }

         uint32_t tight_slot = (got.hdr_flags & BUS_F_INLINE) ? (uint32_t)tight_bound : roomy_slot;
         uint64_t tight_arena = (got.hdr_flags & BUS_F_INLINE) ? roomy_arena : tight_bound;
         if (bus_wire_decode_checked(raw, rawn, tight_slot, tight_arena, &chk) !=
             BUS_WIRE_ERR_PAYLOAD_LEN)
         {
            fprintf(stderr, "vector '%s': checked decode accepted it one byte out of bounds\n",
                    name);
            exit(1);
         }
         geometry_checked++;
      }

      if (negative)
         negatives++;
      n++;
   }
   fclose(fp);

   if (n == 0)
   {
      fprintf(stderr, "vector table is empty\n");
      exit(1);
   }
   for (size_t i = 0; i < REQUIRED_SHAPE_COUNT; i++)
      if (!shape_seen[i])
      {
         fprintf(stderr, "no vector covers: %s (flags 0x%04x)\n", REQUIRED_SHAPES[i].what,
                 REQUIRED_SHAPES[i].flags);
         exit(1);
      }

   if (negatives == 0)
   {
      fprintf(stderr, "vector table has no negative rows — a decoder that accepted\n"
                      "everything would pass conformance against it\n");
      exit(1);
   }
   if (geometry_checked == 0)
   {
      fprintf(stderr, "no payload-bearing vector was run through the checked path\n");
      exit(1);
   }
   printf("  vectors: %zu rows (%zu negative), both directions, %zu geometry-checked,\n"
          "           all %zu shapes covered\n",
          n, negatives, geometry_checked, REQUIRED_SHAPE_COUNT);
   return n;
}

/* ------------------------------------------------------------------ */
/* 2. the pattern matrix, enumerated independently of the table        */

static void check_roundtrip(const char *what, bus_frame_t in)
{
   uint8_t buf[BUS_WIRE_HDR_LEN];
   if (bus_wire_encode(&in, buf, sizeof buf) != BUS_WIRE_HDR_LEN)
   {
      fprintf(stderr, "encode failed: %s\n", what);
      abort();
   }
   bus_frame_t out;
   bus_wire_result_t r = bus_wire_decode(buf, BUS_WIRE_HDR_LEN, &out);
   if (r != BUS_WIRE_OK)
   {
      fprintf(stderr, "decode failed: %s -> %s\n", what, bus_wire_result_name(r));
      abort();
   }
   if (memcmp(&in, &out, sizeof in) != 0)
   {
      fprintf(stderr, "round trip changed the frame: %s\n", what);
      abort();
   }
}

static bus_frame_t base_frame(void)
{
   bus_frame_t f;
   memset(&f, 0, sizeof f);
   f.wire_version = BUS_WIRE_VERSION;
   f.event_kind = BUS_KIND_MODULE_BASE;
   f.principal_ref = 0x11223344u;
   f.src_handle = 7;
   f.logical_ts = 0x0102030405060708ull;
   return f;
}

/* Every pattern crossed with every placement, driven off the flag constants so
 * the matrix follows bus_wire.h rather than a hand-kept list. */
static void test_pattern_matrix(void)
{
   const uint16_t patterns[] = {BUS_F_NOTIFICATION, BUS_F_REQUEST, BUS_F_REPLY, BUS_F_CANCEL};
   const uint16_t placements[] = {0, BUS_F_INLINE, BUS_F_ARENA};
   int cases = 0;

   for (size_t p = 0; p < sizeof patterns / sizeof patterns[0]; p++)
      for (size_t q = 0; q < sizeof placements / sizeof placements[0]; q++)
         for (int control = 0; control <= 1; control++)
         {
            bus_frame_t f = base_frame();
            f.hdr_flags = (uint16_t)(patterns[p] | placements[q] | (control ? BUS_F_CONTROL : 0));
            if (patterns[p] != BUS_F_NOTIFICATION)
               f.correlation_id = 0xdeadbeefcafef00dull;
            if (placements[q] != 0)
            {
               f.payload_len = 128;
               f.payload_ref = placements[q] == BUS_F_INLINE ? BUS_WIRE_HDR_LEN : 0x40000;
            }

            char what[96];
            snprintf(what, sizeof what, "matrix flags=0x%04x", f.hdr_flags);
            check_roundtrip(what, f);
            cases++;
         }

   /* The payload bound from both sides: at the maximum it round-trips, and one
    * byte over is rejected by validate. An off-by-one here would otherwise only
    * surface once a real allocator was involved. */
   bus_frame_t max = base_frame();
   max.hdr_flags = BUS_F_NOTIFICATION | BUS_F_ARENA;
   max.payload_len = BUS_WIRE_MAX_PAYLOAD;
   max.payload_ref = 0x40000;
   check_roundtrip("payload.max", max);
   max.payload_len = BUS_WIRE_MAX_PAYLOAD + 1;
   must(bus_wire_validate(&max) == BUS_WIRE_ERR_PAYLOAD_LEN, "payload bound + 1 rejected");

   printf("  pattern matrix: %d cases + payload bound both sides\n", cases);
}

/* The matrix above round-trips the combinations that are *valid*. This one
 * decides, independently, what every combination should be — including the ones
 * that must be refused — and checks the validator against that judgement rather
 * than against whatever it happens to do.
 *
 * The oracle covers every axis the validator has, not just the flag shape:
 * pattern, placement, payload length against its bound, whether payload_ref is
 * consistent with having a payload at all, and correlation against the pattern.
 * An oracle that judged only flags would have declared the correlation and
 * length rules "covered" while never testing them. */
static void test_combination_matrix(void)
{
   const uint16_t patterns[] = {0,           BUS_F_NOTIFICATION, BUS_F_REQUEST,
                                BUS_F_REPLY, BUS_F_CANCEL,       BUS_F_REQUEST | BUS_F_REPLY};
   const uint16_t placements[] = {0, BUS_F_INLINE, BUS_F_ARENA, BUS_F_INLINE | BUS_F_ARENA};
   const uint32_t lens[] = {0, 64, BUS_WIRE_MAX_PAYLOAD, BUS_WIRE_MAX_PAYLOAD + 1};
   const uint64_t refs[] = {0, 0x40000};
   const uint64_t corrs[] = {0, 0xdeadbeefcafef00dull};
   int accepted = 0, refused = 0;

   for (size_t p = 0; p < sizeof patterns / sizeof patterns[0]; p++)
      for (size_t q = 0; q < sizeof placements / sizeof placements[0]; q++)
         for (size_t l = 0; l < sizeof lens / sizeof lens[0]; l++)
            for (size_t rr = 0; rr < sizeof refs / sizeof refs[0]; rr++)
               for (size_t c = 0; c < sizeof corrs / sizeof corrs[0]; c++)
                  for (int control = 0; control <= 1; control++)
                  {
                     bus_frame_t f = base_frame();
                     f.hdr_flags =
                         (uint16_t)(patterns[p] | placements[q] | (control ? BUS_F_CONTROL : 0));
                     f.payload_len = lens[l];
                     f.payload_ref = refs[rr];
                     f.correlation_id = corrs[c];

                     /* The contract, restated here rather than read back from
                      * the implementation. */
                     int one_pattern =
                         (patterns[p] == BUS_F_NOTIFICATION || patterns[p] == BUS_F_REQUEST ||
                          patterns[p] == BUS_F_REPLY || patterns[p] == BUS_F_CANCEL);
                     int one_placement =
                         (placements[q] == BUS_F_INLINE || placements[q] == BUS_F_ARENA);

                     int placement_ok, length_ok, ref_ok;
                     if (lens[l] > 0)
                     {
                        placement_ok = one_placement;
                        length_ok = lens[l] <= BUS_WIRE_MAX_PAYLOAD;
                        ref_ok = 1; /* any ref is framing-legal with a payload */
                     }
                     else
                     {
                        placement_ok = (placements[q] == 0);
                        length_ok = 1;
                        ref_ok = (refs[rr] == 0); /* no payload means no reference */
                     }

                     int corr_ok;
                     if (patterns[p] == BUS_F_NOTIFICATION)
                        corr_ok = (corrs[c] == 0);
                     else if (one_pattern)
                        corr_ok = (corrs[c] != 0);
                     else
                        corr_ok = 1; /* pattern already refused; do not double-judge */

                     int want_ok = one_pattern && placement_ok && length_ok && ref_ok && corr_ok;

                     bus_wire_result_t got = bus_wire_validate(&f);
                     if (want_ok && got != BUS_WIRE_OK)
                     {
                        fprintf(stderr,
                                "FAIL: flags=0x%04x plen=%u ref=0x%llx corr=0x%llx should be "
                                "accepted, got %s\n",
                                f.hdr_flags, f.payload_len, (unsigned long long)f.payload_ref,
                                (unsigned long long)f.correlation_id, bus_wire_result_name(got));
                        abort();
                     }
                     if (!want_ok && got == BUS_WIRE_OK)
                     {
                        fprintf(stderr,
                                "FAIL: flags=0x%04x plen=%u ref=0x%llx corr=0x%llx should be "
                                "refused\n",
                                f.hdr_flags, f.payload_len, (unsigned long long)f.payload_ref,
                                (unsigned long long)f.correlation_id);
                        abort();
                     }
                     want_ok ? accepted++ : refused++;
                  }

   printf("  combination matrix: %d accepted, %d refused across 5 validator axes\n", accepted,
          refused);
}

/* event_kind, the handles, seq and logical_ts are deliberately unconstrained by
 * this layer: the kind registry belongs to the event-contract schema, and the
 * host assigns handles and seq at routing. Asserting that here keeps the claim
 * honest — "validated message patterns" is a statement about flags and
 * correlation, not about every field in the frame. */
static void test_intentionally_unconstrained_fields(void)
{
   const uint32_t kinds[] = {0, 1, BUS_KIND_MODULE_BASE, UINT32_MAX};
   for (size_t i = 0; i < sizeof kinds / sizeof kinds[0]; i++)
   {
      bus_frame_t f = base_frame();
      f.hdr_flags = BUS_F_NOTIFICATION;
      f.event_kind = kinds[i];
      f.src_handle = UINT32_MAX;
      f.dst_handle = UINT32_MAX;
      f.seq = UINT64_MAX;
      f.logical_ts = UINT64_MAX;
      must(bus_wire_validate(&f) == BUS_WIRE_OK,
           "event_kind, handles, seq and logical_ts are not this layer's to judge");
   }
   printf("  unconstrained fields: kind/handles/seq/ts pass through by design\n");
}

/* The checked decode path must refuse what the raw one accepts, so the safe
 * entry point is genuinely safer rather than just differently named. */
static void test_decode_checked(void)
{
   const uint32_t slot = 256;
   const uint64_t arena = 256; /* small, so the arena bound is distinct from MAX_PAYLOAD */

   /* v2: an ARENA frame's payload_ref is a lease id (not an offset); the only
    * wire-level arena bound is that payload_len not exceed the whole arena. */
   bus_frame_t good = base_frame();
   good.hdr_flags = BUS_F_NOTIFICATION | BUS_F_ARENA;
   good.payload_len = 128;
   good.payload_ref = 3; /* lease id */
   good.generation = 7;

   uint8_t buf[BUS_WIRE_HDR_LEN];
   must(bus_wire_encode(&good, buf, sizeof buf) == BUS_WIRE_HDR_LEN, "encode in-bounds frame");

   bus_frame_t out;
   must(bus_wire_decode_checked(buf, sizeof buf, slot, arena, &out) == BUS_WIRE_OK,
        "checked decode accepts an in-bounds frame");

   /* A payload longer than the whole arena, but structurally perfect. */
   bus_frame_t bad = good;
   bad.payload_len = (uint32_t)arena + 44;
   must(bus_wire_encode(&bad, buf, sizeof buf) == BUS_WIRE_HDR_LEN, "encode out-of-bounds frame");

   memset(&out, 0xa5, sizeof out);
   bus_frame_t before = out;
   must(bus_wire_decode(buf, sizeof buf, &out) == BUS_WIRE_OK,
        "raw decode accepts it — framing is all it can see");
   memset(&out, 0xa5, sizeof out);
   must(bus_wire_decode_checked(buf, sizeof buf, slot, arena, &out) == BUS_WIRE_ERR_PAYLOAD_LEN,
        "checked decode refuses it");
   must(memcmp(&before, &out, sizeof out) == 0, "checked decode leaves *out untouched on refusal");

   /* The checked path takes a different route to committing *out than the raw
    * one — it hands bus_wire_decode a local, so that call's own null guard
    * never sees the caller's pointer. Its guard has to be its own. */
   must(bus_wire_decode_checked(buf, sizeof buf, slot, arena, NULL) != BUS_WIRE_OK,
        "checked decode rejects a null output pointer");
   must(bus_wire_decode_checked(NULL, sizeof buf, slot, arena, &out) != BUS_WIRE_OK,
        "checked decode rejects a null input");
   must(bus_wire_decode(buf, sizeof buf, NULL) != BUS_WIRE_OK,
        "raw decode rejects a null output pointer");

   printf("  checked decode: refuses out-of-bounds frames and null arguments\n");
}

/* ------------------------------------------------------------------ */
/* 3. rejections                                                       */

/* Write a frame the encoder would refuse, so the decoder's own guards can be
 * reached. Offsets mirror bus_wire.c's layout comment. */
static void encode_unchecked(const bus_frame_t *f, uint8_t *out)
{
   bus_frame_t ok = base_frame();
   ok.hdr_flags = BUS_F_NOTIFICATION;
   must(bus_wire_encode(&ok, out, BUS_WIRE_HDR_LEN) == BUS_WIRE_HDR_LEN,
        "encode_unchecked base frame");
   out[4] = (uint8_t)(f->hdr_flags & 0xff);
   out[5] = (uint8_t)((f->hdr_flags >> 8) & 0xff);
   out[6] = (uint8_t)(f->wire_version & 0xff);
   out[7] = (uint8_t)((f->wire_version >> 8) & 0xff);
   for (int i = 0; i < 8; i++)
      out[16 + i] = (uint8_t)((f->correlation_id >> (8 * i)) & 0xff);
   for (int i = 0; i < 8; i++)
      out[40 + i] = (uint8_t)((f->payload_ref >> (8 * i)) & 0xff);
   for (int i = 0; i < 4; i++)
      out[48 + i] = (uint8_t)((f->payload_len >> (8 * i)) & 0xff);
}

static void expect_reject(const char *what, const uint8_t *buf, size_t n, bus_wire_result_t want)
{
   bus_frame_t out;
   memset(&out, 0xa5, sizeof out);
   bus_frame_t before = out;
   bus_wire_result_t r = bus_wire_decode(buf, n, &out);
   if (r != want)
   {
      fprintf(stderr, "%s: expected %s, got %s\n", what, bus_wire_result_name(want),
              bus_wire_result_name(r));
      abort();
   }
   if (memcmp(&before, &out, sizeof out) != 0)
   {
      fprintf(stderr, "%s: decoder wrote to *out on failure\n", what);
      abort();
   }
}

static void test_rejections(void)
{
   uint8_t buf[BUS_WIRE_HDR_LEN], bad[BUS_WIRE_HDR_LEN];
   bus_frame_t good = base_frame();
   good.hdr_flags = BUS_F_NOTIFICATION;
   must(bus_wire_encode(&good, buf, sizeof buf) == BUS_WIRE_HDR_LEN, "encode good frame");

   for (size_t n = 0; n < BUS_WIRE_HDR_LEN; n++)
      expect_reject("short", buf, n, BUS_WIRE_ERR_SHORT);

   memcpy(bad, buf, sizeof bad);
   bad[0] ^= 0xff;
   expect_reject("magic", bad, sizeof bad, BUS_WIRE_ERR_MAGIC);

   /* v2: byte 60 is the arena `generation` field. A non-zero generation on a
    * non-arena frame (buf here is a notification) is a flags violation. */
   memcpy(bad, buf, sizeof bad);
   bad[60] = 1;
   expect_reject("generation_on_non_arena", bad, sizeof bad, BUS_WIRE_ERR_FLAGS);

   struct
   {
      const char *what;
      uint16_t flags;
      uint16_t ver;
      uint64_t corr;
      uint64_t pref;
      uint32_t plen;
      bus_wire_result_t want;
   } cases[] = {
       /* Both sides of the supported version, and zero. A one-sided test would
        * still pass if the validator were loosened to `>= BUS_WIRE_VERSION`. */
       {"version above", BUS_F_NOTIFICATION, BUS_WIRE_VERSION + 1, 0, 0, 0, BUS_WIRE_ERR_VERSION},
       {"version below", BUS_F_NOTIFICATION, BUS_WIRE_VERSION - 1, 0, 0, 0, BUS_WIRE_ERR_VERSION},
       {"version zero", BUS_F_NOTIFICATION, 0, 0, 0, 0, BUS_WIRE_ERR_VERSION},
       {"unknown flag bit", BUS_F_NOTIFICATION | 0x8000u, BUS_WIRE_VERSION, 0, 0, 0,
        BUS_WIRE_ERR_FLAGS},
       {"no pattern", 0, BUS_WIRE_VERSION, 0, 0, 0, BUS_WIRE_ERR_FLAGS},
       {"two patterns", BUS_F_REQUEST | BUS_F_REPLY, BUS_WIRE_VERSION, 1, 0, 0, BUS_WIRE_ERR_FLAGS},
       {"payload without placement", BUS_F_NOTIFICATION, BUS_WIRE_VERSION, 0, 0, 32,
        BUS_WIRE_ERR_FLAGS},
       {"both placements", BUS_F_NOTIFICATION | BUS_F_INLINE | BUS_F_ARENA, BUS_WIRE_VERSION, 0, 0,
        32, BUS_WIRE_ERR_FLAGS},
       {"placement without payload", BUS_F_NOTIFICATION | BUS_F_INLINE, BUS_WIRE_VERSION, 0, 0, 0,
        BUS_WIRE_ERR_FLAGS},
       {"ref without payload", BUS_F_NOTIFICATION, BUS_WIRE_VERSION, 0, 4096, 0,
        BUS_WIRE_ERR_PAYLOAD_LEN},
       {"oversize payload", BUS_F_NOTIFICATION | BUS_F_ARENA, BUS_WIRE_VERSION, 0, 0x40000,
        BUS_WIRE_MAX_PAYLOAD + 1, BUS_WIRE_ERR_PAYLOAD_LEN},
       {"notification with correlation", BUS_F_NOTIFICATION, BUS_WIRE_VERSION, 5, 0, 0,
        BUS_WIRE_ERR_CORRELATION},
       {"request without correlation", BUS_F_REQUEST, BUS_WIRE_VERSION, 0, 0, 0,
        BUS_WIRE_ERR_CORRELATION},
       {"reply without correlation", BUS_F_REPLY, BUS_WIRE_VERSION, 0, 0, 0,
        BUS_WIRE_ERR_CORRELATION},
       {"cancel without correlation", BUS_F_CANCEL, BUS_WIRE_VERSION, 0, 0, 0,
        BUS_WIRE_ERR_CORRELATION},
   };

   for (size_t i = 0; i < sizeof cases / sizeof cases[0]; i++)
   {
      bus_frame_t f = base_frame();
      f.hdr_flags = cases[i].flags;
      f.wire_version = cases[i].ver;
      f.correlation_id = cases[i].corr;
      f.payload_ref = cases[i].pref;
      f.payload_len = cases[i].plen;
      encode_unchecked(&f, bad);
      expect_reject(cases[i].what, bad, sizeof bad, cases[i].want);
      /* The encoder must refuse exactly what the decoder refuses, so a caller
       * cannot build a frame this process would then reject. */
      uint8_t scratch[BUS_WIRE_HDR_LEN];
      must(bus_wire_encode(&f, scratch, sizeof scratch) == 0,
           "encoder must refuse what the decoder refuses");
   }

   must(bus_wire_encode(&good, buf, BUS_WIRE_HDR_LEN - 1) == 0, "encode into a short buffer");

   printf("  rejections: %zu malformed shapes + %d truncations, encoder agrees\n",
          sizeof cases / sizeof cases[0] + 2, BUS_WIRE_HDR_LEN);
}

/* ------------------------------------------------------------------ */
/* 4. placement bounds, which need geometry the codec does not own      */

static void test_placement_bounds(void)
{
   const uint32_t slot = 256;
   const uint64_t arena = 1u << 20;

   bus_frame_t f = base_frame();

   /* Inline: must sit after the header and inside the slot. */
   f.hdr_flags = BUS_F_NOTIFICATION | BUS_F_INLINE;
   f.payload_ref = BUS_WIRE_HDR_LEN;
   f.payload_len = slot - BUS_WIRE_HDR_LEN;
   must(bus_wire_check_placement(&f, slot, arena) == BUS_WIRE_OK, "inline exactly fills slot");

   f.payload_len = slot - BUS_WIRE_HDR_LEN + 1;
   must(bus_wire_check_placement(&f, slot, arena) == BUS_WIRE_ERR_PAYLOAD_LEN,
        "inline one byte past the slot");

   f.payload_ref = BUS_WIRE_HDR_LEN - 1;
   f.payload_len = 8;
   must(bus_wire_check_placement(&f, slot, arena) == BUS_WIRE_ERR_PAYLOAD_LEN,
        "inline overlapping the header");

   /* Arena (v2): payload_ref is a lease id, not an offset; the only wire-level
    * bound is that payload_len not exceed the whole arena (the span's offset is
    * the lease table's business, checked at bus_arena_read_ptr). A small arena,
    * distinct from the MAX_PAYLOAD cap, isolates this bound. */
   const uint64_t small_arena = 4096;
   f.hdr_flags = BUS_F_NOTIFICATION | BUS_F_ARENA;
   f.payload_ref = 5; /* a lease id */
   f.generation = 1;
   f.payload_len = (uint32_t)small_arena;
   must(bus_wire_check_placement(&f, slot, small_arena) == BUS_WIRE_OK,
        "arena length exactly fills the arena");

   f.payload_len = (uint32_t)small_arena + 1;
   must(bus_wire_check_placement(&f, slot, small_arena) == BUS_WIRE_ERR_PAYLOAD_LEN,
        "arena length one byte past the arena");

   /* An empty payload needs no geometry at all. */
   f.hdr_flags = BUS_F_NOTIFICATION;
   f.payload_ref = 0;
   f.payload_len = 0;
   f.generation = 0; /* generation is arena-only; clear the reused frame's value */
   must(bus_wire_check_placement(&f, slot, arena) == BUS_WIRE_OK, "empty payload");

   printf("  placement bounds: slot, arena, header overlap, and 64-bit wrap\n");
}

int main(void)
{
   printf("test_bus_wire:\n");
   verify_vectors();
   test_pattern_matrix();
   test_combination_matrix();
   test_intentionally_unconstrained_fields();
   test_rejections();
   test_placement_bounds();
   test_decode_checked();
   printf("test_bus_wire: OK\n");
   return 0;
}
